// Builds Muster's built-in panel apps (image, chart, table, pr_decision, pr_overview) from
// web/src/panels/apps/ into self-contained HTML files in web/panels/, which the backend embeds
// with include_str!. The generated files are committed so `cargo build` needs no Deno.
//
//   deno task panels           rebuild web/panels/<app>.html
//   deno task panels --check   fail if a committed file is out of date (part of `deno task check`)

export const APPS = ["image", "chart", "table", "pr_decision", "pr_overview"] as const;
const TITLES: Record<typeof APPS[number], string> = {
  image: "Muster image", chart: "Muster chart", table: "Muster table", pr_decision: "Muster PR decision",
  pr_overview: "Muster PR overview",
};
/** Styles an app takes from another app's folder, before its own (pr_decision draws charts). */
const EXTRA_CSS: Partial<Record<typeof APPS[number], string[]>> = { pr_decision: ["chart"] };

const web = new URL("../", import.meta.url);
const read = (path: string) => Deno.readTextFile(new URL(path, web));

async function bundle(entry: string): Promise<string> {
  const out = await new Deno.Command(Deno.execPath(), {
    args: ["bundle", "--platform=browser", "--format=iife", entry],
    cwd: web, stdout: "piped", stderr: "piped",
  }).output();
  if (!out.success) throw new Error(`deno bundle ${entry} failed:\n${new TextDecoder().decode(out.stderr)}`);
  return new TextDecoder().decode(out.stdout);
}

export async function build(app: typeof APPS[number]): Promise<string> {
  let js = await bundle(`src/panels/apps/${app}/main.ts`);
  // Inline script: a literal "</script" would end the element early.
  js = js.replace(/<\/(script)/gi, "<\\/$1");
  if (js.includes("<!--")) throw new Error(`${app}: bundle contains "<!--", which inline scripts cannot hold safely`);
  const parts = ["shared/base.css", ...(EXTRA_CSS[app] ?? []).map((a) => `${a}/style.css`), `${app}/style.css`];
  const css = (await Promise.all(parts.map((p) => read(`src/panels/apps/${p}`)))).join("\n");
  if (/<\/style/i.test(css)) throw new Error(`${app}: CSS contains </style`);
  return `<!doctype html>
<!-- Generated by web/dev/build_panels.ts from web/src/panels/apps/${app}/. Do not edit; run \`deno task panels\`. -->
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${TITLES[app]}</title>
<style>
${css}</style></head><body><main id="app"></main>
<script>
"use strict";
${js}</script></body></html>
`;
}

if (import.meta.main) {
  const check = Deno.args.includes("--check");
  const stale: string[] = [];
  for (const app of APPS) {
    const html = await build(app);
    const target = new URL(`panels/${app}.html`, web);
    const current = await Deno.readTextFile(target).catch(() => "");
    if (current === html) continue;
    if (check) stale.push(`web/panels/${app}.html`);
    else {
      await Deno.writeTextFile(target, html);
      console.log(`wrote web/panels/${app}.html (${html.length} bytes)`);
    }
  }
  if (stale.length) {
    console.error(`Out of date: ${stale.join(", ")}. Run \`cd web && deno task panels\` and commit the result.`);
    Deno.exit(1);
  }
}
